export function zoneColor(p){return p.landuse==='residential'?'#d9ba80':['commercial','retail'].includes(p.landuse)?'#db9ea8':p.landuse==='industrial'?'#b8a4cd':['forest','grass','recreation_ground'].includes(p.landuse)||p.leisure==='park'?'#91b987':['school','university','college','hospital','clinic'].includes(p.amenity)?'#96c4dc':null}
export function polygonParts(f){return f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[]}
export function validPolygon(poly){const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);return poly.length>0&&poly.every(r=>{if(r.length<4||!r.every(p=>p.length>=2&&Number.isFinite(p[0])&&Number.isFinite(p[1]))||r[0][0]!==r.at(-1)[0]||r[0][1]!==r.at(-1)[1])return false;for(let i=0;i<r.length-1;i++)for(let j=i+2;j<r.length-1;j++){if(i===0&&j===r.length-2)continue;const a=r[i],b=r[i+1],c=r[j],d=r[j+1];if(cross(a,b,c)*cross(a,b,d)<0&&cross(c,d,a)*cross(c,d,b)<0)return false}return true})}

